export function applyFixedStudyTypeCopy(selected) {
  if(!selected||!Object.hasOwn(FIXED_STUDY_TYPE_COPY.types,selected.typeId))return selected;
  const copy=FIXED_STUDY_TYPE_COPY.types[selected.typeId];
  const sentences=copy.story.split(/(?<=\.)\s+/u);
  // Keep the existing 3–4-part data contract; the view joins these into one paragraph.
  return {...selected,typeName:copy.name,hanja:copy.hanja,headline:copy.headline,
    description:[sentences.slice(0,2).join(' '),sentences.slice(2,4).join(' '),sentences.slice(4).join(' ')],
    story:copy.story,copyVersion:FIXED_STUDY_TYPE_COPY.copyVersion};
}
